import{_ as e,o as a,c as o,a0 as r}from"./chunks/framework.DzvPB4Y-.js";const f=JSON.parse('{"title":"一维装箱 BPP1D","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/bpp1d/index.md","filePath":"zh-cn/frameworks/bpp1d/index.md"}'),d={name:"zh-cn/frameworks/bpp1d/index.md"};function l(i,t,n,h,c,s){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="一维装箱-bpp1d" tabindex="-1">一维装箱 BPP1D <a class="header-anchor" href="#一维装箱-bpp1d" aria-label="Permalink to &quot;一维装箱 BPP1D&quot;">​</a></h1><p>已有一批长条物品，要放进有限长度的货槽。每种货槽有长度、承重、成本和可用库存；相邻物品可能需要间距。BPP1D 帮你选择装载组合，并生成可复核的放置结果。</p><h2 id="最少需要理解的对象" tabindex="-1">最少需要理解的对象 <a class="header-anchor" href="#最少需要理解的对象" aria-label="Permalink to &quot;最少需要理解的对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务概念</th><th>API</th><th>输入或输出</th></tr></thead><tbody><tr><td>物品</td><td><code>Item</code></td><td>稳定 ID、长度、重量、精确件数</td></tr><tr><td>容器类型</td><td><code>BinType</code></td><td>长度、承重、成本、可选库存</td></tr><tr><td>问题</td><td><code>PackingProblem</code></td><td>物品、容器、间距、目标</td></tr><tr><td>装载组合</td><td><code>PackingPattern</code></td><td>一个容器中各物品的件数</td></tr><tr><td>最终结果</td><td><code>PackingResult</code></td><td>放置、空闲区间、物料和 KPI</td></tr></tbody></table><p>间距只存在于相邻物品之间，不额外收取尾间距。物理量保留单位，不能直接把 <code>40 cm</code> 和裸数 <code>1</code> 比较。</p><h2 id="从哪个入口调用" tabindex="-1">从哪个入口调用？ <a class="header-anchor" href="#从哪个入口调用" aria-label="Permalink to &quot;从哪个入口调用？&quot;">​</a></h2><p>Kotlin 的 <code>Bpp1dMilp</code> / <code>Bpp1dColumnGeneration</code> 注入 <code>ColumnGenerationSolver</code> 和数值适配器。Rust 同名应用入口通过 callback 接收实际 solver 模型；构造和错误处理不应逐行对译。</p><p>你负责数据、目标和后端，框架负责组合生成、模型注册、选择与装载复核。先使用普通 MILP，再观察列生成流程。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><ul><li>这是已有物品的装载模型。需要原料加工、产品产出和超欠产时，比较 <a href="./../csp1d/">CSP1D</a>。</li><li>候选枚举可能受节点数和候选数限制；<code>complete</code> 是需要读取的结果，不是默认假定。</li><li>LP 定价结束不等于整数最优；有限候选池内最优也不自动等于全局最优。</li><li>尾箱重排必须复核完整方案，不能把只适用于全局的业务规则直接当成局部子问题规则。</li></ul><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>完成<a href="./../setup.html">环境准备</a>。</li><li>跟随<a href="./first-packing.html">第一次一维装箱</a>，学习输入、求解、放置和数量复核。</li><li>在同一场景里增加间距、库存、多容器类型和成本，再阅读扩展契约。</li><li>需要自己建模时，参考<a href="/ospf/zh-cn/guide/modeling-workflow.html">建模流程</a>，不要在应用服务里复制已有领域公式。</li></ol><h2 id="接口参考" tabindex="-1">接口参考 <a class="header-anchor" href="#接口参考" aria-label="Permalink to &quot;接口参考&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-bpp1d/README_ch.md" target="_blank" rel="noreferrer">Kotlin API 与扩展契约</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-bpp1d/README_ch.md" target="_blank" rel="noreferrer">Rust API 与扩展契约</a></li><li><a href="/ospf/zh-cn/guide/solving-results.html">理解求解结果</a></li></ul><p><a href="./../">返回场景选型</a></p><h2 id="继续实践" tabindex="-1">继续实践 <a class="header-anchor" href="#继续实践" aria-label="Permalink to &quot;继续实践&quot;">​</a></h2><p>下一课：<a href="./business-scenario.html">多箱型、库存与成本</a>。将场景迁入自己的应用前，完成<a href="./../integration.html">业务接入检查</a>。</p>',17)])])}const m=e(d,[["render",l]]);export{f as __pageData,m as default};
